import React, { useState, useCallback } from 'react';
import { 
  Box, 
  List, 
  ListItem, 
  ListItemIcon, 
  ListItemText, 
  ListItemButton,
  Divider,
  IconButton,
  Collapse,
  useTheme
} from '@mui/material';
import { 
  Home as HomeIcon,
  TrendingUp as TrendingIcon,
  Movie as MovieIcon,
  LiveTv as TvIcon,
  Search as SearchIcon,
  Star as StarIcon,
  Upcoming as UpcomingIcon,
  History as HistoryIcon,
  Favorite as FavoriteIcon,
  ChevronLeft as ChevronLeftIcon,
  ChevronRight as ChevronRightIcon
} from '@mui/icons-material';
import { useNavigate, useLocation } from 'react-router-dom';
import { styled } from '@mui/material/styles';
import { useContext } from 'react';
import { AuthContext } from '../context/AuthContext';

const StyledSidebar = styled(Box)(({ theme, expanded }) => ({
  width: expanded ? 280 : 64,
  height: '100vh',
  position: 'fixed',
  left: 0,
  top: 0,
  backgroundColor: 'rgba(0, 0, 0, 0.8)',
  backdropFilter: 'blur(10px)',
  borderRight: '1px solid rgba(255, 255, 255, 0.1)',
  padding: theme.spacing(2),
  display: 'flex',
  flexDirection: 'column',
  gap: theme.spacing(2),
  zIndex: 1000,
  transition: 'width 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
  '&:hover': {
    width: 280,
  },
}));

const Logo = styled(Box)(({ theme, expanded }) => ({
  fontSize: expanded ? '1.8rem' : '1.2rem',
  fontWeight: 'bold',
  background: 'linear-gradient(45deg, #FF6B6B 30%, #4ECDC4 90%)',
  WebkitBackgroundClip: 'text',
  WebkitTextFillColor: 'transparent',
  padding: theme.spacing(2),
  textAlign: 'center',
  marginBottom: theme.spacing(2),
  whiteSpace: 'nowrap',
  overflow: 'hidden',
  transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
  letterSpacing: '0.5px',
}));

const StyledListItemButton = styled(ListItemButton)(({ theme, active }) => ({
  borderRadius: '12px',
  marginBottom: theme.spacing(1),
  backgroundColor: active ? 'rgba(255, 255, 255, 0.1)' : 'transparent',
  '&:hover': {
    backgroundColor: 'rgba(255, 255, 255, 0.15)',
    transform: 'translateX(5px)',
  },
  transition: 'all 0.3s ease',
  minHeight: 48,
  justifyContent: 'center',
}));

const StyledListItemIcon = styled(ListItemIcon)(({ theme }) => ({
  minWidth: 40,
  color: theme.palette.primary.main,
}));

const StyledListItemText = styled(ListItemText)(({ theme, expanded }) => ({
  opacity: expanded ? 1 : 0,
  transition: 'opacity 0.3s ease',
  '& .MuiTypography-root': {
    fontWeight: 500,
    color: theme.palette.text.primary,
  },
}));

const Sidebar = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const theme = useTheme();
  const { user } = useContext(AuthContext);
  const [expanded, setExpanded] = useState(false);
  const [hoverTimeout, setHoverTimeout] = useState(null);

  const menuItems = [
    { text: 'Home', icon: <HomeIcon />, path: '/' },
    { text: 'Trending', icon: <TrendingIcon />, path: '/trending' },
    { text: 'Popular Movies', icon: <MovieIcon />, path: '/popular/movies' },
    { text: 'Popular TV Shows', icon: <TvIcon />, path: '/popular/tv' },
    { text: 'Top Rated', icon: <StarIcon />, path: '/top-rated' },
    { text: 'Upcoming', icon: <UpcomingIcon />, path: '/upcoming' },
    { text: 'Search', icon: <SearchIcon />, path: '/search' },
  ];

  const userItems = [
    { text: 'Watch History', icon: <HistoryIcon />, path: '/history' },
    { text: 'Favorites', icon: <FavoriteIcon />, path: '/favorites' },
  ];

  const handleMouseEnter = useCallback(() => {
    if (hoverTimeout) {
      clearTimeout(hoverTimeout);
    }
    setExpanded(true);
  }, [hoverTimeout]);

  const handleMouseLeave = useCallback(() => {
    const timeout = setTimeout(() => {
      setExpanded(false);
    }, 300); // Add a delay before collapsing
    setHoverTimeout(timeout);
  }, []);

  return (
    <StyledSidebar 
      expanded={expanded}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <Logo expanded={expanded}>Cineflex</Logo>
      
      <List>
        {menuItems.map((item) => (
          <ListItem key={item.text} disablePadding>
            <StyledListItemButton
              active={location.pathname === item.path ? 1 : 0}
              onClick={() => navigate(item.path)}
            >
              <StyledListItemIcon>{item.icon}</StyledListItemIcon>
              <StyledListItemText primary={item.text} expanded={expanded} />
            </StyledListItemButton>
          </ListItem>
        ))}
      </List>

      {user && (
        <>
          <Divider sx={{ my: 2, borderColor: 'rgba(255, 255, 255, 0.1)' }} />

          <List>
            {userItems.map((item) => (
              <ListItem key={item.text} disablePadding>
                <StyledListItemButton
                  active={location.pathname === item.path ? 1 : 0}
                  onClick={() => navigate(item.path)}
                >
                  <StyledListItemIcon>{item.icon}</StyledListItemIcon>
                  <StyledListItemText primary={item.text} expanded={expanded} />
                </StyledListItemButton>
              </ListItem>
            ))}
          </List>
        </>
      )}
    </StyledSidebar>
  );
};

export default Sidebar;
